const ZIMM_GALLERY_OVERLAY_RECIPE = 'ZimmGalleryOverlay';

type ZimmGalleryOverlayProps = {
  /** Whether the overlay is open. Nothing renders until this and mount-gating (SSR safety) both
   *  clear — see useZimmModal. */
  isOpen: boolean;
  onClose: () => void;
  productName: string;
  /** Ordered photo/video sequence — the same shape/order ZimmProductGallery renders. */
