10	export type ZimmMediaTileWidths = (number | string)[] | Record<string, number | string>;
11	
12	const messages = defineMessages({
13	  play: { id: 'product_gallery.video.play', defaultMessage: 'Play video' },
14	  pause: { id: 'product_gallery.video.pause', defaultMessage: 'Pause video' },
15	  mute: { id: 'product_gallery.video.mute', defaultMessage: 'Mute video' },
