19	const ZIMM_MEDIA_TILE_RECIPE = 'ZimmMediaTile';
20	
21	export type ZimmGalleryPhotoItem = {
22	  kind: 'photo';
23	  src: string;
24	  alt: string;
25	};
26	
27	export type ZimmGalleryVideoItem = {
28	  kind: 'video';
29	  /**
30	   * Poster frame shown in place of real playback. No product video data source exists yet —
31	   * SFCC-188 ("PDP – Product Video in Gallery") is blocked on a content-modelling workshop for
32	   * how video is stored on the product and ordered in the gallery. This renders the positional
33	   * slot and a real, keyboard-operable control shell (play/pause, mute) ready for SFCC-188 to
34	   * wire an actual source into, but the controls only toggle local UI state today.
35	   */
36	  posterSrc: string;
37	  posterAlt: string;
38	};
39	
40	export type ZimmGalleryMediaItem = ZimmGalleryPhotoItem | ZimmGalleryVideoItem;
41	
42	export type ZimmMediaTileProps = {
43	  item: ZimmGalleryMediaItem;
44	  /** Skips `loading="lazy"` — pass for the item that should load with LCP priority. */
45	  eager?: boolean;
46	  /**
47	   * SFCC-731 AC 19 — this tile's own real rendered width per breakpoint (px/vw, or a single
48	   * value), e.g. `{base: '100vw', lg: 902}`. The atom has no layout context of its own — it's
49	   * reused inside full-bleed stacked items, 2/4-up grid cells, and a fluid mobile carousel, each
50	   * a different real width — so each caller supplies its own. When omitted, the image renders
51	   * at its raw source resolution with no responsive `srcset` (this atom's previous behaviour).
52	   */
53	  widths?: ZimmMediaTileWidths;
54	  /** DIS `q` param (0-100), forwarded to `buildDisImageSrc`. Only used when `widths` is given. */
55	  quality?: number;
56	};
57	
58	/**
59	 * Atom — a single photo or video gallery tile's own visual content: aspect-ratio box, the image
60	 * itself (with a load-failure fallback), and — for a video item — its play/pause/mute control
61	 * shell. No interactive "open gallery" trigger behaviour lives here; that's the caller's
62	 * concern (see ZimmProductGallery's sibling `triggerOverlay` button and ZimmGalleryOverlay's
63	 * plain scrollable stack).
64	 *
65	 * Reused across the PDP's default gallery state (ZimmProductGallery) and its expanded/overlay
66	 * state (ZimmGalleryOverlay, SFCC-731 AC 12-25) so the load-failure and aspect-ratio handling
67	 * can't drift between the two.
68	 */
69	export const ZimmMediaTile = ({ item, eager = false, widths, quality }: ZimmMediaTileProps) => {
70	  const intl = useIntl();
71	  const styles = useMultiStyleConfig(ZIMM_MEDIA_TILE_RECIPE, {});
72	  // No real playback source yet (see ZimmGalleryVideoItem) — these toggle local UI state only,
73	  // ready for SFCC-188 to wire a real <video>/Vimeo source behind.
74	  const [playing, setPlaying] = useState(false);
75	  const [muted, setMuted] = useState(true);
76	  // SFCC-731 AC 21 — a failed load keeps the aspect-ratio box (no layout shift) with a neutral
77	  // fill instead of the browser's broken-image icon. Tracks the SOURCE that failed, not a plain
78	  // boolean — a tile is reused at the same list position across renders (index-keyed), so a
79	  // plain boolean would keep showing the fallback for a brand-new, valid source after a
80	  // variation swap replaces a previously-failed one (CodeRabbit, PR #81).
81	  const [erroredSrc, setErroredSrc] = useState<string | null>(null);
82	  const src = item.kind === 'photo' ? item.src : item.posterSrc;
83	  const alt = item.kind === 'photo' ? item.alt : item.posterAlt;
84	  const hasError = erroredSrc === src;
85	
86	  // SFCC-731 AC 19 — responsive DIS srcset when the caller knows its own real rendered width
87	  // (`widths`); otherwise the raw source, unchanged from this atom's previous behaviour. Shared
88	  // between the photo and video-poster branches below so they can't drift from each other.
89	  const image = hasError ? (
90	    <chakra.div __css={styles.mediaFallback} role="img" aria-label={alt} aria-hidden={alt === '' || undefined} />
91	  ) : widths ? (
92	    <DynamicImage
93	      as={Image}
94	      src={buildDisImageSrc(src, quality)}
95	      widths={widths}
96	      imageProps={{
97	        alt,
98	        loading: eager ? 'eager' : 'lazy',
99	        width: '100%',
100	        height: '100%',
101	        objectFit: 'cover',
102	        onError: () => setErroredSrc(src),
103	      }}
104	      // AspectRatio's own CSS (`& > *:not(style)`) sizes DynamicImage's outer Box correctly,
105	      // since that Box is AspectRatio's direct child — but `<picture>` (DynamicImage's own
106	      // markup, one level further in, not exposed as a prop) is `display: inline` by default
107	      // and gets no sizing from anywhere, so the actual image was rendering near its intrinsic
108	      // pixel size instead of filling the tile. `imageProps`'s width/height only reaches the
109	      // innermost <img>, which then has nothing correctly-sized to resolve "100%" against.
110	      __css={{ '& picture': { display: 'block', width: '100%', height: '100%' } }}
111	    />
112	  ) : (
113	    <Image
114	      src={src}
115	      alt={alt}
116	      loading={eager ? 'eager' : 'lazy'}
117	      objectFit="cover"
118	      onError={() => setErroredSrc(src)}
119	    />
120	  );
121	
122	  if (item.kind === 'photo') {
123	    return <AspectRatio ratio={GALLERY_ITEM_ASPECT_RATIO}>{image}</AspectRatio>;
124	  }
125	
126	  return (
127	    <>
128	      <AspectRatio ratio={GALLERY_ITEM_ASPECT_RATIO}>{image}</AspectRatio>
129	      <chakra.div __css={styles.videoControlsWrapper}>
130	        <ZimmButton
131	          variant="icon"
132	          icon={playing ? 'pause' : 'play'}
133	          label={intl.formatMessage(playing ? messages.pause : messages.play)}
134	          onClick={() => setPlaying((p) => !p)}
135	        />
136	        <ZimmButton
137	          variant="icon"
138	          icon="mute"
139	          label={intl.formatMessage(muted ? messages.unmute : messages.mute)}
140	          onClick={() => setMuted((m) => !m)}
141	        />
142	      </chakra.div>
143	    </>
144	  );
145	};
146	
147	export default ZimmMediaTile;
